import{b as o,O as a,g as r,j as e}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"重新认识软件测试","description":"","frontmatter":{},"headers":[],"relativePath":"testing/basics/what-is-testing/index.md","filePath":"测试理论与实践/1.测试基础认知/01.重新认识软件测试.md","lastUpdated":1781509258000}'),l={name:"testing/basics/what-is-testing/index.md"};function u(n,t,i,s,h,q){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="重新认识软件测试" tabindex="-1">重新认识软件测试 <a class="header-anchor" href="#重新认识软件测试" aria-label="Permalink to &quot;重新认识软件测试&quot;">​</a></h1><blockquote><p>纠正你对测试的三个最常见的误解，建立正确的测试观——测试不是为了证明程序没问题，而是为了发现错误。</p></blockquote><h2 id="你以为的测试-vs-实际的测试" tabindex="-1">你以为的测试 vs 实际的测试 <a class="header-anchor" href="#你以为的测试-vs-实际的测试" aria-label="Permalink to &quot;你以为的测试 vs 实际的测试&quot;">​</a></h2><p>很多人以为测试就是&quot;跑一遍功能，确认没问题&quot;。这个理解的问题在于：<strong>你带着&quot;确认没问题&quot;的心态去测，潜意识里会避开那些可能出错的场景</strong>。</p><p>Glenford J. Myers 在《软件测试的艺术》中给出了一个反直觉的经典定义：</p><blockquote><p><strong>测试是为发现错误而执行程序的过程。</strong></p></blockquote><p>注意关键词——&quot;发现错误&quot;，不是&quot;证明正确&quot;。这不是咬文嚼字，而是<strong>心理预设决定测试质量</strong>。就像你做体检，如果目的是&quot;证明自己健康&quot;，有些指标异常你可能觉得&quot;不要紧&quot;；但如果目的是&quot;找出所有毛病&quot;，你会多问几句、查得更细。</p><p>Myers 还补充了一句更扎心的论断：</p><blockquote><p><strong>&quot;成功的测试，是发现了尚未被发现的错误的测试。&quot;</strong></p></blockquote><p>这意味着——测试跑完一个 bug 都没找到，可能不是你测得好，而是你测得不够狠。测试不是&quot;证明软件能用&quot;的仪式，而是<strong>主动破坏、主动寻找弱点的过程</strong>。你越是想办法搞垮它，它就越是能在上线后站得住。</p><h2 id="为什么不能证明程序正确" tabindex="-1">为什么不能证明程序正确 <a class="header-anchor" href="#为什么不能证明程序正确" aria-label="Permalink to &quot;为什么不能证明程序正确&quot;">​</a></h2><h3 id="穷举不可能" tabindex="-1">穷举不可能 <a class="header-anchor" href="#穷举不可能" aria-label="Permalink to &quot;穷举不可能&quot;">​</a></h3><p>假设一个程序有两个输入框，每个输入框接受 1~100 的整数。穷举所有组合需要多少次测试？</p><blockquote><p>100 × 100 = 10,000 次</p></blockquote><p>看起来还行？再加一个下拉框有 10 个选项：</p><blockquote><p>100 × 100 × 10 = 100,000 次</p></blockquote><p>再加一个复选框（2 种状态）：</p><blockquote><p>100 × 100 × 10 × 2 = 200,000 次</p></blockquote><p>真实程序的输入空间是指数级增长的。即使最简单的程序，完全穷举也不现实。而这还只是<strong>黑盒穷举</strong>（只看输入输出组合）。</p><p>白盒穷举（遍历所有代码路径）同样不可行。更关键的是：<strong>即使你遍历了所有代码路径，程序仍然可能有 bug</strong>，比如：</p><ul><li>缺少了本该有的路径（需求没有实现）</li><li>数据敏感型错误（路径走对了，但特定数据会出错）</li><li>接口时序问题（单步没问题，并发时出问题）</li></ul><p>所以核心结论是：<strong>不要指望穷举，要用有限的测试用例发现最多的错误。</strong> 测试的策略性就来源于此。</p><h2 id="测试的心理学" tabindex="-1">测试的心理学 <a class="header-anchor" href="#测试的心理学" aria-label="Permalink to &quot;测试的心理学&quot;">​</a></h2><h3 id="为什么开发者不适合测自己的代码" tabindex="-1">为什么开发者不适合测自己的代码 <a class="header-anchor" href="#为什么开发者不适合测自己的代码" aria-label="Permalink to &quot;为什么开发者不适合测自己的代码&quot;">​</a></h3><p>这不是能力问题，是人性问题：</p><ol><li><strong>思维惯性</strong>：你写的代码，你会沿着写的时候的思路去测。&quot;这个错误处理我写了，不会出问题&quot;——结果恰恰栽在这里</li><li><strong>情感投资</strong>：谁都不愿意承认自己的代码有 bug。潜意识里会回避那些&quot;可能证明自己写错了&quot;的测试</li><li><strong>盲区一致</strong>：写的时候没考虑到的场景，测的时候也不会想到</li></ol><p>一个实用的建议：<strong>测试用例应该在写代码之前设计</strong>。这样你的测试跟代码没有&quot;感情纠葛&quot;，该测什么就测什么。</p><h3 id="测试的三个心理阶段" tabindex="-1">测试的三个心理阶段 <a class="header-anchor" href="#测试的三个心理阶段" aria-label="Permalink to &quot;测试的三个心理阶段&quot;">​</a></h3><p>测试人员的心理也有三个阶段：</p><table tabindex="0"><thead><tr><th>阶段</th><th>心态</th><th>表现</th></tr></thead><tbody><tr><td>初级阶段</td><td>&quot;我要证明它是对的&quot;</td><td>测的都是正常流程，复杂场景不敢碰</td></tr><tr><td>中级阶段</td><td>&quot;我要找到 bug&quot;</td><td>每发现一个 bug 都很兴奋，测试的深度和广度明显提升</td></tr><tr><td>高级阶段</td><td>&quot;我要评估质量风险&quot;</td><td>不只是找 bug，而是判断哪里风险最高、哪些地方最值得测</td></tr></tbody></table><p>第一阶段和第二阶段，测试效果天差地别。这就是为什么反复强调&quot;测试是为了发现错误&quot;——<strong>它改变的不是技术，是心态。</strong></p><h2 id="测试的十大原则" tabindex="-1">测试的十大原则 <a class="header-anchor" href="#测试的十大原则" aria-label="Permalink to &quot;测试的十大原则&quot;">​</a></h2><p>Myers 在书中总结了十条核心测试原则，每一条都是踩坑踩出来的：</p><h3 id="_1-必须定义预期输出" tabindex="-1">1. 必须定义预期输出 <a class="header-anchor" href="#_1-必须定义预期输出" aria-label="Permalink to &quot;1. 必须定义预期输出&quot;">​</a></h3><p>没有预期结果的测试用例，就像没有标准答案的考试。你测完了看到结果，但你不知道这结果对不对。</p><p>❌ 坏例子：&quot;输入账号密码，看能不能登录&quot; ✅ 好例子：&quot;输入正确账号密码，预期：跳转到首页，右上角显示用户名；输入错误密码，预期：页面停留，底部出现红色提示&#39;账号或密码错误&#39;，持续 3 秒后消失&quot;</p><h3 id="_2-程序员应避免测试自己的程序" tabindex="-1">2. 程序员应避免测试自己的程序 <a class="header-anchor" href="#_2-程序员应避免测试自己的程序" aria-label="Permalink to &quot;2. 程序员应避免测试自己的程序&quot;">​</a></h3><p>上一节已经讲了原因。但注意，这不等于&quot;开发者不写测试&quot;——单元测试是开发者写，但系统测试和验收测试应该由独立的人来做。</p><h3 id="_3-应仔细检查每个测试结果" tabindex="-1">3. 应仔细检查每个测试结果 <a class="header-anchor" href="#_3-应仔细检查每个测试结果" aria-label="Permalink to &quot;3. 应仔细检查每个测试结果&quot;">​</a></h3><p>自动化测试跑完，你真的看了每一条失败的用例吗？很多时候连续失败是因为同一个根因，但也有可能不同失败背后是不同的 bug。<strong>对&quot;看起来一样&quot;的失败保持警惕。</strong></p><h3 id="_4-测试用例应包含有效和无效输入" tabindex="-1">4. 测试用例应包含有效和无效输入 <a class="header-anchor" href="#_4-测试用例应包含有效和无效输入" aria-label="Permalink to &quot;4. 测试用例应包含有效和无效输入&quot;">​</a></h3><p>只测正常流程是最常见的测试陷阱。用户输错格式、网络断了、数据库挂了——这些&quot;异常&quot;恰恰是线上事故的高发区。</p><h3 id="_5-测试应基于用户视角" tabindex="-1">5. 测试应基于用户视角 <a class="header-anchor" href="#_5-测试应基于用户视角" aria-label="Permalink to &quot;5. 测试应基于用户视角&quot;">​</a></h3><p>你不是在测代码，是在测用户能不能完成任务。代码逻辑正确 ≠ 用户能用。举个例子：注册流程代码全部跑通，但验证码字体太小、老年用户根本看不清——这在用户视角就是不能用。</p><h3 id="_6-充分注意测试中的集群现象" tabindex="-1">6. 充分注意测试中的集群现象 <a class="header-anchor" href="#_6-充分注意测试中的集群现象" aria-label="Permalink to &quot;6. 充分注意测试中的集群现象&quot;">​</a></h3><p>bug 不是均匀分布的。一个模块发现了 3 个 bug，它后面可能还藏着 10 个。<strong>发现 bug 越多的模块，越值得重点测。</strong></p><h3 id="_7-避免测试用例的杀虫剂效应" tabindex="-1">7. 避免测试用例的杀虫剂效应 <a class="header-anchor" href="#_7-避免测试用例的杀虫剂效应" aria-label="Permalink to &quot;7. 避免测试用例的杀虫剂效应&quot;">​</a></h3><p>相同的一批测试用例反复执行，就像杀虫剂用久了害虫会产生抗药性。测试用例需要定期更新和补充，否则新 bug 会在老用例的盲区里滋生。</p><h3 id="_8-测试应因地制宜" tabindex="-1">8. 测试应因地制宜 <a class="header-anchor" href="#_8-测试应因地制宜" aria-label="Permalink to &quot;8. 测试应因地制宜&quot;">​</a></h3><p>金融系统的测试重点和社交 App 完全不同。没有&quot;万能测试策略&quot;，只有&quot;适合当前项目的测试策略&quot;。</p><h3 id="_9-测试需要创造力和智力" tabindex="-1">9. 测试需要创造力和智力 <a class="header-anchor" href="#_9-测试需要创造力和智力" aria-label="Permalink to &quot;9. 测试需要创造力和智力&quot;">​</a></h3><p>测试不是机械劳动。好的测试人员像侦探——从蛛丝马迹中推断哪里可能出问题，然后设计实验验证。</p><h3 id="_10-提防-没有发现错误的测试是有价值的-这种错觉" tabindex="-1">10. 提防&quot;没有发现错误的测试是有价值的&quot;这种错觉 <a class="header-anchor" href="#_10-提防-没有发现错误的测试是有价值的-这种错觉" aria-label="Permalink to &quot;10. 提防&quot;没有发现错误的测试是有价值的&quot;这种错觉&quot;">​</a></h3><p>没发现 bug 不等于代码没问题，也可能是因为你测得不够深。<strong>测试的价值不体现在&quot;发现 0 个 bug&quot;，体现在&quot;我们已经充分测试了高风险区域，未发现严重问题&quot;。</strong></p><h2 id="质量-测试" tabindex="-1">质量 ≠ 测试 <a class="header-anchor" href="#质量-测试" aria-label="Permalink to &quot;质量 ≠ 测试&quot;">​</a></h2><p>《Google 软件测试之道》中有一个核心理念：<strong>质量是开发过程的产物，不是测试测出来的。</strong></p><p>可以这样理解：</p><ul><li><strong>测试是温度计</strong>——它能量出体温（发现 bug），但不能退烧（修复 bug）</li><li><strong>质量是身体素质</strong>——靠的是饮食、运动、作息，不靠天天量体温</li></ul><p>测试团队的目标不是&quot;把质量测出来&quot;，而是<strong>提供关于产品质量的准确信息</strong>，帮助团队做出决策：能不能上线？哪里需要加强？</p><p>这也是为什么&quot;开发者对质量负首要责任&quot;这个理念越来越被认可——质量应该在编码阶段就内建进去，而不是等到测试阶段再去补救。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试的经典定义：<strong>为发现错误而执行程序的过程</strong>——心理预设决定测试效果</li><li>穷举测试永远不可行（无论黑盒还是白盒），因此测试的核心挑战是<strong>用有限用例发现最多错误</strong></li><li>开发者不适合测自己的代码——思维惯性、情感投资、盲区一致</li><li>测试的十大原则中，最关键的三条：<strong>必须定义预期输出、覆盖有效和无效输入、警惕杀虫剂效应</strong></li><li>质量 ≠ 测试：测试提供质量信息，但不是质量的来源。开发生命周期的早期阶段才是质量的决定性因素</li></ol>',62)])])}const b=o(l,[["render",u]]);export{p as __pageData,b as default};
